const position = world.getPosition(bot);

// Use the bot's current block position as the pyramid's center and base level.
const centerX = Math.floor(position.x);
const baseY = Math.floor(position.y);
const centerZ = Math.floor(position.z);

const baseSize = 21; // Use an odd number to keep the pyramid centered.
const height = Math.ceil(baseSize / 2);

const startX = centerX - Math.floor(baseSize / 2);
const startZ = centerZ - Math.floor(baseSize / 2);

for (let layer = 0; layer < height; layer++) {
    const size = baseSize - 2 * layer;
    const y = baseY + layer;

    for (let x = startX + layer; x < startX + layer + size; x++) {
        for (let z = startZ + layer; z < startZ + layer + size; z++) {
            await skills.placeBlock(bot, 'sandstone', x, y, z);
        }
    }
}
```

