fn modPow(base: u64, exponent: u64, modulus: u64) u64 {
    var result: u64 = 1;
    var b = base % modulus;
    var e = exponent;

    while (e > 0) : (e /= 2) {
        if (e % 2 == 1) result = (result * b) % modulus;
        b = (b * b) % modulus;
    }
    return result;
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;
    const input = try std.fs.cwd().readFileAlloc(allocator, "input.txt", 4096);
    defer allocator.free(input);

