### My answer to the prompt

A reliable approach is to measure the full text at the available width before deciding whether to show the link. In the collapsed layout, put the text and a separate tappable “See more” next to each other so the link cannot itself be truncated.

```jsx
// ExpandableText.js
import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

export default function ExpandableText({
  text = '',
  style,
  linkStyle,
  linkText = 'See more',
}) {
  const [width, setWidth] = useState(0);
  const [isExpanded, setIsExpanded] = useState(false);
  const [overflows, setOverflows] = useState(false);

  useEffect(() => {
    setIsExpanded(false);
    setOverflows(false);
  }, [text]);

  return (
    <View
      style={styles.container}
      onLayout={({ nativeEvent }) => setWidth(nativeEvent.layout.width)}
    >
      {isExpanded ? (
        <Text style={style}>{text}</Text>
      ) : (
        <View style={styles.row}>
          <Text style={[styles.text, style]} numberOfLines={1}>
            {text}
          </Text>
          {overflows && (
            <Text
              accessibilityRole="button"
              onPress={() => setIsExpanded(true)}
